}

.user-text-inline{
	--user-text-line-height:1.25em;
	overflow:hidden;
	text-overflow:ellipsis;
	white-space:nowrap;
	line-height:1.25em;
	line-height:var(--user-text-line-height);
	max-height:1.25em;
	max-height:var(--user-text-line-height);
	display:inline-block;
	vertical-align:bottom;
	max-width:100%;
}

.user-text-flex{
	--user-text-line-height:1.25em;
	overflow:hidden;
	text-overflow:ellipsis;
	white-space:nowrap;
	min-width:0;
	line-height:1.25em;
